#!/bin/bash\n\necho \"========================================\"\necho \"Game Boy Rail Shooter Editor - Build Script\"\necho \"========================================\"\necho \"\"\n\necho \"Installing Python dependencies...\"\npython3 -m pip install --upgrade pip > /dev/null 2>&1\npython3 -m pip install -r requirements.txt > /dev/null 2>&1\npython3 -m pip install -r build_requirements.txt > /dev/null 2>&1\n\necho \"Building executable...\"\npyinstaller --onefile --windowed --name \"GameBoy Rail Shooter Editor\" run_editor.py\n\necho \"\"\necho \"========================================\"\nif [ -f \"dist/GameBoy Rail Shooter Editor\" ]; then\n    echo \"[SUCCESS] Build complete!\"\n    echo \"Executable: dist/GameBoy Rail Shooter Editor\"\nelse\n    echo \"[ERROR] Build failed. Check PyInstaller output above.\"\nfi\necho \"========================================\"\necho \"\"\n